      "html": "<div style=\"font-size:1.25cqw;letter-spacing:0.34em;text-transform:uppercase;color:#C39A38;font-weight:600\">Challenge</div>\n  <div style=\"height:0.2083cqw;background:#C39A38;width:6.875cqw;margin:1.5625cqw 0 0\"></div>\n  <div style=\"display:flex;flex-direction:column;gap:1.7708cqw;margin-top:2.9167cqw\">\n    <div style=\"display:flex;gap:1.7708cqw;align-items:baseline\"><div style=\"font-family:var(--deck-display),system-ui,sans-serif;font-weight:800;font-size:2.0833cqw;color:#C39A38;flex:none;width:3.9583cqw\">01</div><div style=\"font-size:3.6458cqw;line-height:1.24;text-wrap:pretty;font-weight:500\">Read the Bible daily</div></div>\n    <div style=\"display:flex;gap:1.7708cqw;align-items:baseline\"><div style=\"font-family:var(--deck-display),system-ui,sans-serif;font-weight:800;font-size:2.0833cqw;color:#C39A38;flex:none;width:3.9583cqw\">02</div><div style=\"font-size:3.6458cqw;line-height:1.24;text-wrap:pretty;font-weight:500\">Begin with the Gospel of John</div></div>\n    <div style=\"display:flex;gap:1.7708cqw;align-items:baseline\"><div style=\"font-family:var(--deck-display),system-ui,sans-serif;font-weight:800;font-size:2.0833cqw;color:#C39A38;flex:none;width:3.9583cqw\">03</div><div style=\"font-size:3.6458cqw;line-height:1.24;text-wrap:pretty;font-weight:500\">Apply what you learn</div></div>\n    <div style=\"display:flex;gap:1.7708cqw;align-items:baseline\"><div style=\"font-family:var(--deck-display),system-ui,sans-serif;font-weight:800;font-size:2.0833cqw;color:#C39A38;flex:none;width:3.9583cqw\">04</div><div style=\"font-size:3.6458cqw;line-height:1.24;text-wrap:pretty;font-weight:500\">Make God’s Word your standard</div></div>\n  </div>\n  <div style=\"position:absolute;left:5cqw;right:5.4167cqw;bottom:2.3958cqw;display:flex;align-items:baseline;justify-content:space-between;padding-top:1.3542cqw;border-top:0.1042cqw solid rgba(195,154,56,0.45)\">\n    <div style=\"font-size:1.25cqw;letter-spacing:0.24em;text-transform:uppercase;color:#C39A38;font-weight:600\">Lesson 02 · Word of God</div>\n    <div style=\"display:flex;align-items:baseline;gap:1.5625cqw\">\n      <div style=\"font-size:1.25cqw;letter-spacing:0.2em;text-transform:uppercase;color:#C39A38\">Book p. 30</div>\n      <div style=\"font-size:1.3542cqw;font-family:var(--deck-display),system-ui,sans-serif;font-weight:800;color:#123F72\">23</div>\n    </div>\n  </div>"
